import type { ReactNode } from 'react'
import { Tabs as BaseTabs } from '@base-ui/react/tabs'
import { cn } from '@/lib/utils'
import styles from './Tabs.module.css'

export interface TabItem {
  value: string
  label: ReactNode
  /** The panel shown while this tab is selected. */
  content?: ReactNode
  icon?: ReactNode
  disabled?: boolean
}

export interface TabsProps {
  items: TabItem[]
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  /** `underline`: a line under the selected tab. `pills`: a filled segment, for switching views in a toolbar. */
  appearance?: 'underline' | 'pills'
  size?: 'sm' | 'md'
  orientation?: 'horizontal' | 'vertical'
  /** Tabs share the full width equally. */
  isFullWidth?: boolean
  /** Select a tab as soon as it gets focus, rather than on Enter or Space. */
  activateOnFocus?: boolean
  /** Keep hidden panels in the DOM, e.g. to preserve their state. */
  keepMounted?: boolean
  /** Names the tab list when nothing on the page does. */
  'aria-label'?: string
  className?: string
}

export function Tabs({
  items,
  value,
  defaultValue,
  onValueChange,
  appearance = 'underline',
  size = 'md',
  orientation = 'horizontal',
  isFullWidth = false,
  activateOnFocus = false,
  keepMounted = false,
  'aria-label': ariaLabel,
  className,
}: TabsProps) {
  return (
    <BaseTabs.Root
      value={value}
      defaultValue={defaultValue ?? (value === undefined ? items.find((i) => !i.disabled)?.value : undefined)}
      onValueChange={onValueChange && ((v) => onValueChange(v as string))}
      orientation={orientation}
      className={cn(styles.tabs, styles[appearance], styles[size], styles[orientation], isFullWidth && styles.fullWidth, className)}
    >
      <BaseTabs.List className={styles.list} activateOnFocus={activateOnFocus} aria-label={ariaLabel}>
        {items.map((item) => (
          <BaseTabs.Tab key={item.value} value={item.value} disabled={item.disabled} className={styles.tab}>
            {item.icon && (
              <span className={styles.icon} aria-hidden="true">
                {item.icon}
              </span>
            )}
            {item.label}
          </BaseTabs.Tab>
        ))}
        <BaseTabs.Indicator className={styles.indicator} />
      </BaseTabs.List>
      {items.map(
        (item) =>
          item.content !== undefined && (
            <BaseTabs.Panel key={item.value} value={item.value} keepMounted={keepMounted} className={styles.panel}>
              {item.content}
            </BaseTabs.Panel>
          ),
      )}
    </BaseTabs.Root>
  )
}

.tabs {
  --tab-height: var(--space-10);
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  color: var(--foreground);
}

.sm {
  --tab-height: var(--space-8);
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
}

.vertical {
  flex-direction: row;
}

.list {
  position: relative;
  z-index: 0;
  display: flex;
  gap: var(--space-1);
}
.vertical .list {
  flex-direction: column;
  align-self: flex-start;
}

.tab {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  box-sizing: border-box;
  min-block-size: var(--tab-height);
  margin: 0;
  padding: 0 var(--space-3);
  border: 0;
  border-radius: var(--radius-control);
  background: transparent;
  color: var(--muted-foreground);
  font: inherit;
  font-weight: 500;
  white-space: nowrap;
  cursor: var(--cursor-button);
  transition:
    color 150ms,
    background-color 150ms;
}
.vertical .tab {
  justify-content: flex-start;
}
.fullWidth .tab {
  flex: 1;
}

.tab:hover:not([data-disabled]) {
  color: var(--foreground);
}
.tab[data-active] {
  color: var(--foreground);
}
.tab[data-disabled] {
  opacity: 0.5;
  cursor: var(--cursor-disabled);
}
.tab:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
}

.icon {
  display: inline-flex;
  font-size: var(--space-4);
}

/* underline: a rule under the whole list, and a 2px bar under the
   selected tab that slides between tabs. */
.underline .list {
  box-shadow: inset 0 -1px var(--border);
}
.underline.vertical .list {
  box-shadow: inset -1px 0 var(--border);
}
.underline .tab {
  border-radius: var(--radius-sm);
}
.underline .indicator {
  position: absolute;
  inset-inline-start: var(--active-tab-left);
  inset-block-end: 0;
  inline-size: var(--active-tab-width);
  block-size: 2px;
  background: var(--foreground);
  transition:
    inset-inline-start 200ms,
    inline-size 200ms;
}
.underline.vertical .indicator {
  inset-inline-start: auto;
  inset-inline-end: 0;
  inset-block-start: var(--active-tab-top);
  inset-block-end: auto;
  inline-size: 2px;
  block-size: var(--active-tab-height);
  transition:
    inset-block-start 200ms,
    block-size 200ms;
}

/* pills: a track in --muted, the selected tab lifted onto --background. */
.pills .list {
  padding: var(--space-1);
  border-radius: var(--radius-field);
  background: var(--muted);
}
.pills.horizontal .list {
  align-self: flex-start;
}
.pills.fullWidth .list {
  align-self: stretch;
}
.pills .tab {
  min-block-size: calc(var(--tab-height) - 2 * var(--space-1));
  /* --muted-foreground is 4.3:1 on the --muted track, under 4.5. */
  color: var(--foreground);
}
.pills .indicator {
  position: absolute;
  z-index: -1;
  inset-inline-start: var(--active-tab-left);
  inset-block-start: var(--active-tab-top);
  inline-size: var(--active-tab-width);
  block-size: var(--active-tab-height);
  box-sizing: border-box;
  /* The border, not just the lighter fill, marks the selected tab: white
     on --muted alone is barely 1.1:1. */
  border: 1px solid var(--control-border);
  border-radius: var(--radius-control);
  background: var(--background);
  box-shadow: var(--shadow-xs);
  transition:
    inset-inline-start 200ms,
    inset-block-start 200ms,
    inline-size 200ms,
    block-size 200ms;
}

.panel {
  outline: none;
}
.panel:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

@media (pointer: coarse) {
  .tab {
    min-block-size: 44px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .indicator {
    transition: none;
  }
}
